def transformer_block(x, attn, mlp, ln1, ln2):
    x = x + attn(ln1(x))               # mix across tokens
    x = x + mlp(ln2(x))                # transform each token
    return x

# a stack is just this block, repeated
def transformer(x, blocks):
    for blk in blocks:
        x = blk(x)
    return x
